verify:
choices = {o: choices[n] for o, n in {'C': 'A', 'B': 'B', 'D': 'C', 'A': 'D'}.items()}; answer = {'A': 'C', 'B': 'B', 'C': 'D', 'D': 'A'}[answer]  # shuffled: original letters
x = symbols('x')
def vert(k):
    e = value(choices[k].split('=')[1])
    xv = solve(diff(e, x), x)[0]
    return xv, e.subs(x, xv)
def q4(p):
    return p[0] > 0 and p[1] < 0
assert vert(answer) == (2, -3) and q4(vert(answer))
assert all(not q4(vert(k)) for k in choices if k != answer)
